366.     this.updatePresentation(event.source);
367.     const action = this.contextualizeAction(event.action);
368.     if (this.handleMobileTextInput(action)) return;
369.     if (action === "battleLogUp" || action === "battleLogDown") {
370.       this.dispatchWheel(action === "battleLogUp" ? -120 : 120);
371.       return;
372.     }
373.     const descriptor = event.token && event.repeated
374.       ? this.heldSyntheticKeys.get(event.token)
375.       : this.keyForAction(action);
376.     if (!descriptor) return;
377.     if (event.token) {
378.       this.pressSyntheticToken(event.token, descriptor, event.repeated);
379.     } else {
380.       this.dispatchKey("keydown", descriptor, event.repeated);
381.       window.setTimeout(() => this.dispatchKey("keyup", descriptor, false), 0);
382.     }
383.   }
384. 
385.   private pressSyntheticToken(
386.     token: string,
387.     descriptor: KeyDescriptor,
388.     repeated: boolean,
389.     dispatchInitial = true,
390.   ): void {
391.     const existing = this.heldSyntheticKeys.get(token);
392.     if (repeated && existing) {
393.       this.dispatchKey("keydown", existing, true);
394.       return;
395.     }
396.     if (existing) return;
397.     this.heldSyntheticKeys.set(token, descriptor);
398.     const firstOwner = this.syntheticKeyOwnership.acquire(
399.       token,
400.       descriptor.code,
401.     );
402.     if (dispatchInitial && firstOwner) {
403.       this.dispatchKey("keydown", descriptor, false);
404.     }
405.   }
406. 
407.   private releaseSyntheticToken(token: string): void {
408.     const descriptor = this.heldSyntheticKeys.get(token);
409.     if (!descriptor) return;
410.     this.heldSyntheticKeys.delete(token);
411.     const release = this.syntheticKeyOwnership.release(token);
412.     if (release?.finalOwner) {
413.       this.dispatchKey("keyup", descriptor, false);
414.     }
415.   }
