417.   private contextualizeAction(action: InputAction): InputAction {
418.     const context = this.getContext();
419.     if (context === "exploration" && action.startsWith("navigate")) {
420.       return action.replace("navigate", "move") as InputAction;
421.     }
422.     if (context === "cutscene" || context === "ending") {
423.       if (action === "confirm" || action === "interact") return "cutsceneAdvance";
424.       if (action === "cancel") return "cutsceneSkip";
425.     }
426.     if (context === "inventory") {
427.       const inventoryActions: Partial<Record<InputAction, InputAction>> = {
428.         navigateUp: "inventoryPrevious",
429.         navigateDown: "inventoryNext",
430.         navigateLeft: "inventoryPagePrevious",
431.         navigateRight: "inventoryPageNext",
432.         confirm: "inventoryPrimary",
433.       };
434.       return inventoryActions[action] ?? action;
435.     }
436.     if (context === "codex") {
437.       if (action === "interact") return "codexSearch";
438.       if (action === "battleTargetPrevious") return "codexCategoryPrevious";
439.       if (action === "battleTargetNext") return "codexCategoryNext";
440.     }
441.     return action;
442.   }
443. 
444.   private keyForAction(action: InputAction): KeyDescriptor | undefined {
445.     if (
446.       (
447.         this.getContext() === "shop"
448.         || this.getContext() === "chronicle"
449.       )
450.       && action.startsWith("navigate")
451.     ) {
452.       const direction = action.slice("navigate".length);
453.       return { code: `Arrow${direction}`, key: `Arrow${direction}` };
454.     }
455.     if (
456.       this.getContext() === "characterCreation"
457.       && action.startsWith("navigate")
458.     ) {
459.       const direction = action.slice("navigate".length);
460.       return { code: `Arrow${direction}`, key: `Arrow${direction}` };
461.     }
462.     if (
463.       this.getContext() === "characterCreation"
464.       && (action === "confirm" || action === "interact")
465.     ) {
466.       return { code: "Enter", key: "Enter" };
467.     }
468.     return ACTION_KEYS[action];
469.   }
