471.   private dispatchKey(
472.     type: "keydown" | "keyup",
473.     descriptor: KeyDescriptor,
474.     repeat: boolean,
475.   ): void {
476.     const event = new KeyboardEvent(type, {
477.       bubbles: true,
478.       cancelable: true,
479.       code: descriptor.code,
480.       key: descriptor.key,
481.       repeat,
482.     });
483.     const keyCode = descriptor.keyCode ?? this.keyCodeFor(descriptor.code);
484.     Object.defineProperty(event, "keyCode", { value: keyCode });
485.     Object.defineProperty(event, "which", { value: keyCode });
486.     this.syntheticEvents.add(event);
487.     window.dispatchEvent(event);
488.   }
489. 
490.   private keyCodeFor(code: string): number {
491.     const fixed: Readonly<Record<string, number>> = {
492.       Backspace: 8,
493.       Tab: 9,
494.       Enter: 13,
495.       Escape: 27,
496.       Space: 32,
497.       PageUp: 33,
498.       PageDown: 34,
499.       End: 35,
500.       Home: 36,
501.       ArrowLeft: 37,
502.       ArrowUp: 38,
503.       ArrowRight: 39,
504.       ArrowDown: 40,
505.       F1: 112,
506.       Slash: 191,
507.     };
508.     if (fixed[code] !== undefined) return fixed[code];
509.     if (code.startsWith("Key") && code.length === 4) {
510.       return code.charCodeAt(3);
511.     }
512.     return 0;
513.   }
