515.   private releaseAllSyntheticKeys(): void {
516.     const descriptors = new Map<string, KeyDescriptor>();
517.     for (const descriptor of this.heldSyntheticKeys.values()) {
518.       descriptors.set(descriptor.code, descriptor);
519.     }
520.     this.heldSyntheticKeys.clear();

520.     this.heldSyntheticKeys.clear();
521.     this.syntheticKeyOwnership.clear();
522.     for (const descriptor of descriptors.values()) {
523.       this.dispatchKey("keyup", descriptor, false);
524.     }
525.   }
