554.   private createTouchControls(): void {
555.     const root = document.createElement("div");
556.     root.id = "touch-controls";
557.     root.setAttribute("aria-label", "Touch game controls");
558.     for (const definition of TOUCH_BUTTONS) {
559.       const button = document.createElement("button");
560.       button.type = "button";
561.       button.className = `touch-control ${definition.className}`;
562.       button.dataset.action = definition.action;
563.       button.textContent = definition.label;
564.       button.setAttribute("aria-label", definition.action);
565.       let lastPointerActivation = Number.NEGATIVE_INFINITY;
566.       const pulse = (): void => {
567.         const inputEvent = this.state.pulse(
568.           this.contextualizeAction(definition.action),
569.           "touch",
570.           now(),
571.         );
572.         if (inputEvent) this.dispatch(inputEvent);
573.       };
574.       button.addEventListener("pointerdown", (event) => {
575.         event.preventDefault();
576.         if (!HELD_TOUCH_ACTIONS.has(definition.action)) {
577.           inputSource.set("touch");
578.           this.updatePresentation("touch");
579.           return;
580.         }
581.         if (event.isTrusted) button.setPointerCapture(event.pointerId);
582.         const action = this.contextualizeAction(definition.action);
583.         const token = `touch:${event.pointerId}:${definition.action}`;
584.         const inputEvent = this.state.press(token, action, "touch", now());
585.         if (inputEvent) {
586.           this.dispatch(inputEvent);
587.         } else {
588.           const descriptor = this.keyForAction(action);
589.           if (descriptor) {
590.             this.pressSyntheticToken(token, descriptor, false, false);
591.           }
592.         }
593.       });
594.       const releaseHeld = (event: PointerEvent): void => {
595.         const token = `touch:${event.pointerId}:${definition.action}`;
596.         this.state.release(token);
597.         window.setTimeout(() => this.releaseSyntheticToken(token), 40);
598.         if (button.hasPointerCapture(event.pointerId)) {
599.           button.releasePointerCapture(event.pointerId);
600.         }
601.       };
602.       button.addEventListener("pointerup", (event) => {
603.         event.preventDefault();
604.         if (HELD_TOUCH_ACTIONS.has(definition.action)) {
605.           releaseHeld(event);
606.           return;
607.         }
608.         lastPointerActivation = now();
609.         pulse();
610.       });
611.       button.addEventListener("pointercancel", (event) => {
612.         if (HELD_TOUCH_ACTIONS.has(definition.action)) releaseHeld(event);
613.       });
614.       button.addEventListener("lostpointercapture", (event) => {
615.         const token = `touch:${event.pointerId}:${definition.action}`;
616.         this.state.release(token);
617.         window.setTimeout(() => this.releaseSyntheticToken(token), 40);
618.       });
619.       button.addEventListener("click", (event) => {
620.         if (HELD_TOUCH_ACTIONS.has(definition.action)) return;
621.         event.preventDefault();
622.         if (now() - lastPointerActivation <= TOUCH_CLICK_SUPPRESSION_MS) return;
623.         pulse();
624.       });
625.       root.append(button);
626.     }
627.     document.getElementById("game-inner")?.append(root);
628.     this.touchRoot = root;
629.     this.applyFeatureAvailability();
630.   }
