632.   private applyFeatureAvailability(): void {
633.     if (!this.touchRoot) return;
634.     for (const button of this.touchRoot.querySelectorAll<HTMLButtonElement>(
635.       ".touch-control",
636.     )) {
637.       const action = button.dataset.action;
638.       const featureId = action
639.         ? getInputActionFeature(action as InputAction)
640.         : undefined;
641.       button.hidden = featureId !== undefined
642.         && !featureAvailability.has(featureId);
643.     }
644.   }
