704.   private handleMobileTextInput(action: InputAction): boolean {
705.     const form = document.getElementById("mobile-text-input");
706.     if (!(form instanceof HTMLFormElement)) return false;
707.     if (
708.       action === "confirm"
709.       || action === "interact"
710.       || action === "inventoryPrimary"
711.     ) {
712.       form.requestSubmit();
713.     } else if (
714.       action === "cancel"
715.       || action === "openMenu"
716.     ) {
717.       const cancel = form.querySelector<HTMLButtonElement>(
718.         'button[type="button"]',
719.       );
720.       cancel?.click();
721.     }
722.     return true;
723.   }
