729.   private getContext(): InputContext {
730.     const key = this.getActiveSceneKey();
731.     if (key === "BootScene") {
732.       const state = document.getElementById("debug-state")?.textContent ?? "";
733.       return state.includes("Screen: title") ? "title" : "characterCreation";
734.     }
735.     if (key === "OverworldScene") {
736.       const state = document.getElementById("debug-state")?.textContent ?? "";
737.       if (state.includes("[PARTY:items")) return "inventory";
738.       if (state.includes("[GATHERING")) return "gathering";
739.       if (state.includes("[CHRONICLE]")) return "chronicle";
740.       if (
741.         state.includes("[PARTY:")
742.         || state.includes("[MENU]")
743.         || state.includes("[SAVE_SLOTS:")
744.         || state.includes("[TIPS")
745.         || state.includes("[WORLD_EVENT:")
746.       ) {
747.         return "overlay";
748.       }
749.       return "exploration";
750.     }
751.     if (key === "ShopScene") return "shop";
752.     if (key === "CodexScene") return "codex";
753.     if (key === "BattleScene") return "battle";
754.     if (key === "CutsceneScene") return "cutscene";
755.     if (key === "EndingScene") return "ending";
756.     if (key === "DefeatScene") return "result";
757.     return "overlay";
758.   }
759. }
