761. export function openMobileTextInput(
762.   label: string,
763.   initialValue: string,
764.   maximumLength: number,
765.   onCommit: (value: string) => void,
766. ): void {
767.   const existing = document.getElementById("mobile-text-input");
768.   existing?.remove();
769.   const form = document.createElement("form");
770.   form.id = "mobile-text-input";
771.   form.setAttribute("aria-label", label);
772.   const input = document.createElement("input");
773.   input.type = "text";
774.   input.value = initialValue;
775.   input.maxLength = maximumLength;
776.   input.autocomplete = "off";
777.   input.setAttribute("aria-label", label);
778.   const commit = document.createElement("button");
779.   commit.type = "submit";
780.   commit.textContent = "Done";
781.   const cancel = document.createElement("button");
782.   cancel.type = "button";
783.   cancel.textContent = "Cancel";
784.   const close = (): void => form.remove();
785.   const stopGamePropagation = (event: KeyboardEvent): void => {
786.     event.stopPropagation();
787.   };
788.   form.addEventListener("keydown", stopGamePropagation);
789.   form.addEventListener("keyup", stopGamePropagation);
790.   form.addEventListener("submit", (event) => {
791.     event.preventDefault();
792.     onCommit(input.value);
793.     close();
794.   });
795.   cancel.addEventListener("click", close);
796.   form.append(input, commit, cancel);
797.   document.body.append(form);
798.   input.focus();
799.   input.select();
800. }
