194. export function mapKeyboardCode(
195.   code: string,
196.   context: InputContext,
197. ): InputAction | undefined {
198.   if (code === "Enter" || code === "Space") {
199.     return context === "exploration" ? "interact" : "confirm";
200.   }
201.   if (code.startsWith("Arrow")) {
202.     const direction = code.slice("Arrow".length) as
203.       | "Up"
204.       | "Down"
205.       | "Left"
206.       | "Right";
207.     return directionalAction(direction, context);
208.   }
209.   const wasd: Readonly<Record<string, "Up" | "Down" | "Left" | "Right">> = {
210.     KeyW: "Up",
211.     KeyS: "Down",
212.     KeyA: "Left",
213.     KeyD: "Right",
214.   };
215.   const direction = wasd[code];
216.   if (direction) return directionalAction(direction, context);
217.   if (context === "inventory") {
