330.   private continueGame(slotId: SaveSlotId = "autosave"): void {
331.     if (this.sceneTransitions.isPending) return;
332.     const save = loadGame(slotId);
333.     if (!save) return;
334.     const defeatedBosses = new Set(save.defeatedBosses);
335.     const weatherState = save.weatherState ?? createWeatherState();
336.     const timeStep = save.timeStep ?? 0;
337.     const pendingCutsceneId = getNextPendingCutscene(save.player.progression);
338.     saveGame(
339.       save.player,
340.       defeatedBosses,

340.       defeatedBosses,
341.       save.codex,
342.       save.player.appearanceId,
343.       timeStep,
344.       weatherState,
345.     );
346.     this.sceneTransitions.startWithFade(() => {
347.       const state = {
348.         player: save.player,
349.         defeatedBosses,
350.         codex: save.codex,
351.         timeStep,
352.         weatherState,
353.         savedSpecialNpcs: [],
354.       };
355.       if (pendingCutsceneId === CAMPAIGN_EPILOGUE_CUTSCENE_ID) {
356.         this.scene.start("EndingScene", {
357.           ...state,
358.           cutsceneId: pendingCutsceneId,
359.           replay: false,
360.         });
361.       } else if (pendingCutsceneId) {
362.         this.scene.start("CutsceneScene", {
363.           ...state,
364.           cutsceneId: pendingCutsceneId,
365.           replay: false,
366.         });
367.       } else {
368.         this.scene.start("OverworldScene", state);
369.       }
370.     }, {
371.       duration: 500,
372.       label: "continue game",
373.     });
374.   }
