181.   private readonly poll = (timestamp: number): void => {
182.     const sceneKey = this.getActiveSceneKey();
183.     const context = this.getContext();
184.     if (sceneKey !== this.activeSceneKey || context !== this.activeContext) {
185.       this.closeMobileTextInput();
186.       this.releaseAllSyntheticKeys();
187.       this.state.clear();
188.       this.activeSceneKey = sceneKey;
189.       this.activeContext = context;
190.       this.cursorActive = false;
191.       this.updateCursor();
192.       this.applyTouchActionAvailability(context);
193.     }
194.     this.pollGamepads(timestamp);
195.     for (const event of this.state.update(timestamp)) this.dispatch(event);
196.     this.animationFrame = window.requestAnimationFrame(this.poll);
197.   };
